Array.prototype.myMap = function (callback) {
  const result = [];
  for (let i = 0; i < this.length; i++) {
    result.push(callback(this[i], i, this));
  }
  return result;
};

const marks = [7, , 9];
let calls = 0;
const mine = marks.myMap((m) => { calls++; return m * 2; });
const real = marks.map((m) => m * 2);

console.log(calls);
console.log(1 in mine, 1 in real);
console.log(mine.join(","), real.join(","));
